---RefreshView 刷新按钮样式
---@param questId integer @ 关卡id
---@param currentQuestId integer @ 当前挑战的关卡id
---@param passedQuestId integer @ 过关的关卡id
function GachaCoinQuestBattleButton:RefreshView(questId, currentQuestId, passedQuestId)
    -- 设置任务id
    self:SetQuestId(questId)
    self.currentQuestId = currentQuestId

    -- 刷新按钮状态
    KTool.SetActive(self.controller, true)
    local questType = GCQUtils.GetGachaCoinQuestTypeById(questId)
    if GCQConstants.Defines.QuestType.Normal == questType then
        self:RefreshButtonNormalQuest(questId, currentQuestId, passedQuestId)
    elseif GCQConstants.Defines.QuestType.Challenge == questType then
        self:RefreshButtonChallengeQuest(questId, currentQuestId, passedQuestId)
    else
        KTool.SetActive(self.controller, false)
    end
end

---RefreshButtonNormalQuest 刷新普通关卡的按钮版式
---@param questId integer @ 关卡id
---@param currentQuestId integer @ 当前挑战的关卡id
---@param passedQuestId integer @ 过关的关卡id
function GachaCoinQuestBattleButton:RefreshButtonNormalQuest(questId, currentQuestId, passedQuestId)
    local unlock = GCQUtils.IsQuestUnlock(questId, passedQuestId)

    -- 隐藏挑战模式提示
    KTool.SetActive(self.ChallengeHintInfo.gameObject, false)

    -- 刷新解锁状态
    self:RefreshByUnlock(unlock)

    -- 刷新是否正在挑战版式
    self:RefreshByIsCurrent(questId, currentQuestId)

    -- 刷新消耗信息
    local needShowCost = not GCQUtils.CheckCurrentQuestId(currentQuestId)
    self:RefreshCostInfo(questId, needShowCost)
end

---RefreshByUnlock 根据是否解锁刷新按钮
---@param unlock boolean 是否解锁该关卡
function GachaCoinQuestBattleButton:RefreshByUnlock(unlock)
    -- 未解锁文字
    KTool.SetActive(self.LockLabel.gameObject, not unlock)
    -- 战斗按钮
    KTool.SetActive(self.BattleButton.gameObject, unlock)
end

---RefreshByIsCurrent 刷新是否正在挑战该关卡
---@param questId integer @ 关卡id
---@param currentQuestId integer @ 当前挑战的关卡id
function GachaCoinQuestBattleButton:RefreshByIsCurrent(questId, currentQuestId)
    local isCurrentQuest = GCQUtils.CheckCurrentQuestId(currentQuestId) and currentQuestId == questId or false
    -- 正在挑战 显示取消按钮
    KTool.SetActive(self.CancelBtn.gameObject, isCurrentQuest)
    -- 刷新底板大小
    local size = Vector2(280, 70)
    if true == isCurrentQuest then
        size.x = 375
    end
    self.BattleBtnBg.sizeDelta = size
    -- 设置按钮是否可用
    local enable = isCurrentQuest or not GCQUtils.CheckCurrentQuestId(currentQuestId)
    self.BattleButton.interactable = enable
    if currentQuestId ~= 0 then
        self.Text.text = enable and localize("继续出击") or localize("出击")
    else
        self.Text.text = localize("出击")
    end
end

---RefreshCostInfo 刷新消耗信息
---@param questId integer @ 关卡id
---@param showCostInfo boolean 是否需要显示消耗信息
function GachaCoinQuestBattleButton:RefreshCostInfo(questId, showCostInfo)
    local questConfig = GCQUtils.GetGachaCoinQuestConfigById(questId)
    if not isNull(questConfig) then

        -- 道具图标
        local costGoodsId = checkInt(questConfig.costItem)
        local costGoodsIcon = GoodsConfMgr:GetPhotoPathById(costGoodsId)
        if not isNull(costGoodsIcon) then
            -- 刷新道具图标
            self.CostGoodsIcon:LoadSprite(costGoodsIcon)
        end

        -- 道具数量
        self.CostGoodsAmount.text = questConfig.costNumLose

    end

    -- 是否需要显示消耗
    KTool.SetActive(self.CostInfoBg.gameObject, showCostInfo)
end

---RefreshButtonChallengeQuest 刷新挑战关卡的按钮版式
---@param questId integer @ 关卡id
---@param currentQuestId integer @ 当前挑战的关卡id
---@param passedQuestId integer @ 过关的关卡id
function GachaCoinQuestBattleButton:RefreshButtonChallengeQuest(questId, currentQuestId, passedQuestId)
    -- 挑战模式不显示放弃按钮
    self:RefreshByIsCurrent(questId, currentQuestId)
    -- 显示挑战模式的提示文字
    KTool.SetActive(self.ChallengeHintInfo.gameObject, true)
    -- 隐藏消耗信息
    KTool.SetActive(self.CostInfoBg.gameObject, false)
    -- 刷新按钮状态
    local unlock = GCQUtils.IsQuestUnlock(questId, passedQuestId)
    self.BattleButton.interactable = unlock
end


