---StartQuest 开始任务
function GachaCoinQuestBattleButton:StartQuest()
    local questId = self:GetQuestId()
    local questType = GCQUtils.GetGachaCoinQuestTypeById(questId)

    if GCQConstants.Defines.QuestType.Challenge == questType then
        -- 挑战模式直接进入选人
        self:ReadyEnterBattle(questId)
    else
        -- 其他模式判断是否需要消耗第一次进入的资源
        local hasCurrentQuest = GCQUtils.CheckCurrentQuestId(self.currentQuestId)
        if not hasCurrentQuest then
            -- 判断是否满足消耗
            local canStartQuest, warningStr = self:CanStartQuest(questId)
            if not canStartQuest then
                GameUtils.Toast(warningStr)
            else
                -- 可以开始任务 不单独请求 直接进入选人
                self:ReadyEnterBattle(questId)
            end
        else
            -- 可以开始任务 不单独请求 直接进入选人
            self:ReadyEnterBattle(questId)
        end
    end
end

---CanStartQuest 是否可以开始任务
---@param questId integer @ 任务id
---@return boolean, string @ 是否可以开始任务,错误信息
function GachaCoinQuestBattleButton:CanStartQuest(questId)
    local costGoodsId, costGoodsAmount = GCQUtils.GetQuestCostInfo(questId)
    --print(costGoodsId, costGoodsAmount, questId)
    if nil ~= costGoodsId and 0 < costGoodsAmount then
        -- 查询道具是否满足条件
        if costGoodsAmount > GoodsUtils.GetThingNo(costGoodsId) then
            -- 道具不足
            local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(costGoodsId)
            local warningStr = localize('_name_数量不足', {_name_= vo.name})
            return false, warningStr
        end
    end
    return true
end

---ReadyEnterBattle 准备进入战斗
---@param questId integer @ 任务id
function GachaCoinQuestBattleButton:ReadyEnterBattle(questId)
    local homeData = GCQUtils.GetHomeDojo()
    local battleType = GCQUtils.GetBattleTypeByQuestId(questId)
    local parameters = {
        battleType = battleType,
        levelId = questId,
        bossHpPercent = checkNumber(homeData.bossHpPercent),
        cardsInfo = homeData.cardsInfo,
    }
    UIModule.OpenDialog(
        {id = Constants.UITypeIds.UIFightTeamChoose,  parameters = parameters},
        {
            {id = Constants.UITypeIds.UIGachaCoinQuestDialog}
        }
    )
end

---GiveUpQuest 放弃当前任务
function GachaCoinQuestBattleButton:GiveUpQuest()
    local questId = self.questId
    GameUtils.Request(
        Interfaces.GachaCoinQuestHomeRenounceQuest, {copyId = questId},
        function (request, response)
            if 0 == checkInt(response.errCode) then
                -- 放弃挑战成功
                self:GiveUpQuestHandler(response.data)
            else
                GameUtils.Toast(response.errMsg)
            end
        end
    )

    -- debug --
    -- self:GiveUpQuestHandler()
    -- debug --
end
---GiveUpQuestHandler 放弃当前任务请求处理
function GachaCoinQuestBattleButton:GiveUpQuestHandler(responseData)
    -- 重置数据
    ---@type GachaCoinQuestComponent
    local gachaCoinQuestComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.GachaCoinQuestComponent)
    gachaCoinQuestComponent:GiveUpQuest()

    ---@type TeamComponent
    local teamComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.TeamComponent)
    --放弃之后队伍和血量信息全部清除
    teamComponent:ClearTeamBySystemId(Constants.SystemToggleIds.Id11)
end


