---BattleButtonClickHandler 战斗按钮
function GachaCoinQuestBattleButton:BattleButtonClickHandler()
    if not self.BattleButton.interactable then return end
    self:StartQuest()
end

---CancelButtonClickHandler 取消按钮回调
function GachaCoinQuestBattleButton:CancelButtonClickHandler()
    -- 取消当前正在进行的任务
    GameUtils.SecondConfirm(
        localize('是否退出本关挑战?'),
        Bind(self, self.GiveUpQuest),
        nil,
        localize('退出战斗后进度将会重置')
    )
end


